//! TableAggregate: the scaffold of `io.angzarr.examples.v1.TableState`, written once by
//! `angzarr scaffold rust` and yours from then on: `--missing` adds the
//! stubs it lacks.
//!
//! A thin adapter: every handler and applier delegates to agg-table's
//! [`TableLogic`], which holds the logic with no harness in it. Generated by
//! the scaffold from a copy of the spec's protos with the component
//! references it cannot resolve removed (see the crate README); each
//! hand edit to its output is marked `HAND-EDIT`.

use agg_table::{AfterAction, Table, TableLogic};
use angzarr_embedded::next::markup::{Context, Emit, Refuses};
use angzarr_embedded_macros::{aggregate, applies, handles_cmd};
use examples_proto::v1::TableState;

use crate::domain::*;
use crate::refused::TableRefused;

// HAND-EDIT: the scaffold writes `pub struct TableAggregate {}`; the
// aggregate holds agg-table's `Table`.
#[derive(Clone, Debug, Default)]
pub struct TableAggregate {
    table: Table,
}

// HAND-EDIT: not scaffolded. The state, for tests and readers.
impl TableAggregate {
    /// The folded state.
    pub fn state(&self) -> &TableState {
        self.table.state()
    }

    /// The step after the deal and after every action, as events.
    fn after_action(&self, _ctx: &Context) -> Result<Emit<Self>, TableRefused> {
        Ok(match self.table.after_action() {
            AfterAction::Turn(turn) => Emit::of(TurnStarted(turn)),
            AfterAction::Settle(dealer, settled) => {
                Emit::of((DealerPlayed(dealer), RoundSettled(settled)))
            }
            AfterAction::Nothing => Emit::of(None::<TurnStarted>),
        })
    }

    /// DealRound's second step: the deal, then the step after it.
    fn deal(&self, _ctx: &Context) -> Result<Emit<Self>, TableRefused> {
        Ok(Emit::of(RoundDealt(self.table.deal()?)).then(Self::after_action))
    }
}

// HAND-EDIT throughout the handlers: the scaffold types every rejection
// `Infallible` (table.proto lists its rejection codes only in comments), so
// each is `TableRefused`; and it types a command's result from its `emits`
// as one fixed tuple, so Hit, Stand and DoubleDown (which emit a variable
// subset) are `Emit<Self>` with the after-action step, and RequestSeat and
// ConfirmSeat (whose repeats emit nothing) are `Option`.
#[aggregate(domain = "table")]
impl TableAggregate {
    #[handles_cmd(CreateTable)]
    fn create_table(
        &self,
        cmd: CreateTable,
        ctx: &Context,
    ) -> Result<(TableCreated, ShoeShuffled), TableRefused> {
        let _ = ctx;
        let (created, shuffled) = self.table.create_table(&cmd.0)?;
        Ok((TableCreated(created), ShoeShuffled(shuffled)))
    }

    #[handles_cmd(RequestSeat)]
    fn request_seat(
        &self,
        cmd: RequestSeat,
        ctx: &Context,
    ) -> Result<Option<SeatHeld>, TableRefused> {
        let _ = ctx;
        Ok(self.table.request_seat(&cmd.0)?.map(SeatHeld))
    }

    #[handles_cmd(LeaveTable)]
    fn leave_table(&self, cmd: LeaveTable, ctx: &Context) -> Result<PlayerCashedOut, TableRefused> {
        let _ = (cmd, ctx);
        todo!("LeaveTable is deferred tonight")
    }

    #[handles_cmd(PlaceBet)]
    fn place_bet(&self, cmd: PlaceBet, ctx: &Context) -> Result<BetPlaced, TableRefused> {
        let _ = ctx;
        Ok(BetPlaced(self.table.place_bet(&cmd.0)?))
    }

    #[handles_cmd(DealRound)]
    fn deal_round(&self, cmd: DealRound, ctx: &Context) -> Result<Emit<Self>, TableRefused> {
        let _ = ctx;
        let reshuffle = self.table.deal_round(&cmd.0)?.map(ShoeShuffled);
        Ok(Emit::of(reshuffle).then(Self::deal))
    }

    #[handles_cmd(Hit)]
    fn hit(&self, cmd: Hit, ctx: &Context) -> Result<Emit<Self>, TableRefused> {
        let _ = ctx;
        Ok(Emit::of(CardDealt(self.table.hit(&cmd.0)?)).then(Self::after_action))
    }

    #[handles_cmd(Stand)]
    fn stand(&self, cmd: Stand, ctx: &Context) -> Result<Emit<Self>, TableRefused> {
        let _ = ctx;
        Ok(Emit::of(HandStood(self.table.stand(&cmd.0)?)).then(Self::after_action))
    }

    #[handles_cmd(DoubleDown)]
    fn double_down(&self, cmd: DoubleDown, ctx: &Context) -> Result<Emit<Self>, TableRefused> {
        let _ = ctx;
        Ok(Emit::of(HandDoubled(self.table.double_down(&cmd.0)?)).then(Self::after_action))
    }

    #[handles_cmd(ConfirmSeat, refuses(SeatNotConfirmable))]
    fn confirm_seat(
        &self,
        cmd: ConfirmSeat,
        ctx: &Context,
    ) -> Result<Option<PlayerSeated>, Refuses<Self, ConfirmSeat>> {
        let _ = ctx;
        match self.table.confirm_seat(&cmd.0) {
            Ok(seated) => Ok(seated.map(PlayerSeated)),
            Err(refusal) => Err(SeatNotConfirmable(refusal).into()),
        }
    }

    #[handles_cmd(ReleaseSeat)]
    fn release_seat(&self, cmd: ReleaseSeat, ctx: &Context) -> Result<SeatReleased, TableRefused> {
        let _ = (cmd, ctx);
        todo!("ReleaseSeat is deferred tonight")
    }

    #[applies(TableCreated)]
    fn table_created(&mut self, event: TableCreated) {
        self.table.apply_table_created(&event.0);
    }

    #[applies(ShoeShuffled)]
    fn shoe_shuffled(&mut self, event: ShoeShuffled) {
        self.table.apply_shoe_shuffled(&event.0);
    }

    #[applies(SeatHeld)]
    fn seat_held(&mut self, event: SeatHeld) {
        self.table.apply_seat_held(&event.0);
    }

    #[applies(SeatReleased)]
    fn seat_released(&mut self, event: SeatReleased) {
        let _ = event;
        todo!("ReleaseSeat is deferred tonight")
    }

    #[applies(PlayerSeated)]
    fn player_seated(&mut self, event: PlayerSeated) {
        self.table.apply_player_seated(&event.0);
    }

    #[applies(PlayerCashedOut)]
    fn player_cashed_out(&mut self, event: PlayerCashedOut) {
        let _ = event;
        todo!("LeaveTable is deferred tonight")
    }

    #[applies(BetPlaced)]
    fn bet_placed(&mut self, event: BetPlaced) {
        self.table.apply_bet_placed(&event.0);
    }

    #[applies(RoundDealt)]
    fn round_dealt(&mut self, event: RoundDealt) {
        self.table.apply_round_dealt(&event.0);
    }

    #[applies(TurnStarted)]
    fn turn_started(&mut self, event: TurnStarted) {
        self.table.apply_turn_started(&event.0);
    }

    #[applies(CardDealt)]
    fn card_dealt(&mut self, event: CardDealt) {
        self.table.apply_card_dealt(&event.0);
    }

    #[applies(HandStood)]
    fn hand_stood(&mut self, event: HandStood) {
        self.table.apply_hand_stood(&event.0);
    }

    #[applies(HandDoubled)]
    fn hand_doubled(&mut self, event: HandDoubled) {
        self.table.apply_hand_doubled(&event.0);
    }

    #[applies(DealerPlayed)]
    fn dealer_played(&mut self, event: DealerPlayed) {
        self.table.apply_dealer_played(&event.0);
    }

    #[applies(RoundSettled)]
    fn round_settled(&mut self, event: RoundSettled) {
        self.table.apply_round_settled(&event.0);
    }
}

